import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, mix, uv, add, sub } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new THREE.Group();
  const timelines = [];
  const cellGroups = [];

  // Layout constants
  const gridWidth = 5.5;
  const gridHeight = 3.5;
  const gutterSize = 0.25;
  const dominantWidth = 3.25;
  const dominantHeight = 3.5;
  const secondaryWidth = 2.0;
  const secondaryHeight = (gridHeight - gutterSize) / 2;
  const cellDepth = 0.06;
  const cellPadding = 0.5;

  // Colors
  const gradientStart = '#101017';
  const gradientEnd = '#1a1a22';
  const accentColor = '#ff2a38';

  // Grid positions (centered at origin)
  const gridLeft = -gridWidth / 2;
  const gridTop = gridHeight / 2;
  const dominantX = gridLeft + dominantWidth / 2;
  const dominantY = 0;
  const secondaryLeft = gridLeft + dominantWidth + gutterSize;
  const secondaryX = secondaryLeft + secondaryWidth / 2;
  const secondary1Y = gridTop - secondaryHeight / 2;
  const secondary2Y = gridTop - gutterSize - secondaryHeight - secondaryHeight / 2;

  function createCell(width, height, x, y, textItems) {
    const cellGroup = new THREE.Group();
    cellGroup.position.set(x, y, 0);

    // Main slab with procedural gradient
    const slabGeo = new THREE.BoxGeometry(width, height, cellDepth, 8, 8);
    const uvNode = uv();
    const gradNode = mix(
      color(gradientStart),
      color(gradientEnd),
      add(sub(uvNode.y, uvNode.x), 1).mul(0.5)
    );

    const slabMat = new MeshStandardNodeMaterial({
      colorNode: gradNode,
      roughness: 0.5,
      metalness: 0.45,
      clearcoat: 0.2,
      transparent: true,
      opacity: 0
    });

    const slab = new THREE.Mesh(slabGeo, slabMat);
    cellGroup.add(slab);

    // Accent tick bar
    const tickGeo = new THREE.PlaneGeometry(0.4, 0.05);
    const tickMat = new MeshStandardNodeMaterial({
      colorNode: color(accentColor),
      emissive: color(accentColor),
      emissiveIntensity: 1.3,
      roughness: 0,
      metalness: 0,
      transparent: true,
      opacity: 0,
      toneMapped: false
    });
    const tick = new THREE.Mesh(tickGeo, tickMat);
    tick.position.set(
      -width / 2 + cellPadding + 0.2,
      height / 2 - cellPadding - 0.025,
      cellDepth / 2 + 0.01
    );
    tick.scale.z = 0.01;
    cellGroup.add(tick);

    // Text elements
    const textElements = [];
    for (const item of textItems) {
      const txtMesh = ctx.fontAtlas.createText(item.text, {
        fontSize: item.fontSize,
        color: '#e8ecf2',
        align: 'left'
      });
      txtMesh.position.copy(item.pos);
      txtMesh.position.z = 0.1;
      gsap.set(txtMesh, { opacity: 0 });
      cellGroup.add(txtMesh);
      textElements.push(txtMesh);
    }

    // Set initial y offset for fade-up animation
    gsap.set(cellGroup, { y: y + 0.2 });

    cellGroups.push({
      group: cellGroup,
      meshMat: slabMat,
      tickMat: tickMat,
      texts: textElements,
      targetY: y
    });

    return cellGroup;
  }

  // Dominant cell (left, full height)
  const dominantCell = createCell(
    dominantWidth,
    dominantHeight,
    dominantX,
    dominantY,
    [
      {
        text: '0.002 mm',
        fontSize: 124,
        pos: new THREE.Vector3(-dominantWidth / 2 + cellPadding, 0.25, 0.1)
      },
      {
        text: 'Case tolerance, CNC pass',
        fontSize: 18,
        pos: new THREE.Vector3(-dominantWidth / 2 + cellPadding, -0.25, 0.1)
      }
    ]
  );
  root.add(dominantCell);

  // Secondary cell 1 (top right)
  const secondary1Cell = createCell(
    secondaryWidth,
    secondaryHeight,
    secondaryX,
    secondary1Y,
    [
      {
        text: '38 h',
        fontSize: 68,
        pos: new THREE.Vector3(-secondaryWidth / 2 + cellPadding, 0.08, 0.1)
      },
      {
        text: 'Power reserve, NA-01',
        fontSize: 18,
        pos: new THREE.Vector3(-secondaryWidth / 2 + cellPadding, -0.4, 0.1)
      }
    ]
  );
  root.add(secondary1Cell);

  // Secondary cell 2 (bottom right)
  const secondary2Cell = createCell(
    secondaryWidth,
    secondaryHeight,
    secondaryX,
    secondary2Y,
    [
      {
        text: '214',
        fontSize: 68,
        pos: new THREE.Vector3(-secondaryWidth / 2 + cellPadding, 0.08, 0.1)
      },
      {
        text: 'Components per calibre',
        fontSize: 18,
        pos: new THREE.Vector3(-secondaryWidth / 2 + cellPadding, -0.4, 0.1)
      }
    ]
  );
  root.add(secondary2Cell);

  // Grid header
  const headerText = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.12
  });
  headerText.position.set(gridLeft, gridTop + 0.5, 0.1);
  gsap.set(headerText, { opacity: 0 });
  root.add(headerText);

  // Entrance animation: stagger-cards with fade-up
  const entranceTL = gsap.timeline();
  const staggerDelay = 0.08;

  cellGroups.forEach((cell, idx) => {
    const offset = idx * staggerDelay;

    // Mesh opacity
    entranceTL.to(
      cell.meshMat,
      {
        opacity: 1,
        duration: 0.5,
        ease: 'power2.out',
        onUpdate: () => (cell.meshMat.needsUpdate = true)
      },
      offset
    );

    // Tick opacity
    entranceTL.to(
      cell.tickMat,
      {
        opacity: 1,
        duration: 0.5,
        ease: 'power2.out',
        onUpdate: () => (cell.tickMat.needsUpdate = true)
      },
      offset
    );

    // Cell y position (fade-up)
    entranceTL.to(
      cell.group.position,
      {
        y: cell.targetY,
        duration: 0.5,
        ease: 'power2.out'
      },
      offset
    );

    // Text opacity
    cell.texts.forEach((txt) => {
      entranceTL.to(
        txt,
        {
          opacity: 1,
          duration: 0.5,
          ease: 'power2.out'
        },
        offset
      );
    });
  });

  // Header entrance
  entranceTL.to(
    headerText,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'power2.out'
    },
    0
  );

  timelines.push(entranceTL);

  // Hover interactions
  root.userData.handlers = {};
  cellGroups.forEach((cell, idx) => {
    root.userData.handlers[`cell-${idx}-hover`] = () => {
      gsap.to(cell.group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out'
      });
    };

    root.userData.handlers[`cell-${idx}-unhover`] = () => {
      const settleTL = gsap.timeline();
      settleTL.to(cell.group.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04,
        duration: 0.9,
        ease: 'power4.out'
      });
      settleTL.to(
        cell.group.scale,
        {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.15,
          ease: 'power2.out'
        },
        '>-0.15'
      );
      timelines.push(settleTL);
    };
  });

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
